policies.inbound:







                application/json

            {"error":"Request body too large"}




<set-variable name="credentials" value="@{
        var header = context.Request.Headers.GetValueOrDefault("Authorization", "");
        if (!header.StartsWith("Basic ", StringComparison.OrdinalIgnoreCase)) {
            return new string[0];
        }
        try {
            var decoded = Encoding.UTF8.GetString(Convert.FromBase64String(header.Substring(6).Trim()));
            var separator = decoded.IndexOf(':');
            if (separator < 0) {
                return new string[0];
            }
            var username = decoded.Substring(0, separator);
            var password = decoded.Substring(separator + 1);
            if (!Regex.IsMatch(username, @"^[a-z0-9-]{3,40}\z") || password.Length == 0 || password.Length > 256) {
                return new string[0];
            }
            return new string[] { username, password };
        } catch {
            return new string[0];
        }
    }" />





