                        Basic realm="pcs-bulk-claims"


                        application/json

                    {"error":"Unauthorized"}



        <set-variable name="clientSecret" value="@((string)((IResponse)context.Variables["clientKeyVaultResponse"]).Body.As()["value"])" />




<set-variable name="organisationId" value="@{
        try {
            var secret = JObject.Parse((string)context.Variables["clientSecret"]);
            if (!(bool)secret["enabled"]) {
                return "";
            }
            var salt = Convert.FromBase64String((string)secret["salt"]);
            var expected = Convert.FromBase64String((string)secret["passwordHash"]);
            var password = ((string[])context.Variables["credentials"])[1];
            var actual = new HMACSHA256(salt).ComputeHash(Encoding.UTF8.GetBytes(password));
            if (actual.Length != expected.Length) {
                return "";
            }
            int difference = 0;
            for (int i = 0; i < actual.Length; i++) {
                difference |= actual[i] ^ expected[i];
            }
            if (difference != 0) {
                return "";
            }
            var organisationId = (string)secret["organisationId"];
            return Regex.IsMatch(organisationId, @"^[A-Za-z0-9]{3,32}\z") ? organisationId : "";
        } catch {
            return "";
        }
    }" />





